def solve(grid):
    """Count the number of islands (connected components of 1s) in a possibly jagged grid.
    Cells are connected orthogonally (up, down, left, right). Empty rows are handled.
    """
    if not grid:
        return 0
    rows = len(grid)
    count = 0
    for i in range(rows):
        cols = len(grid[i])
        for j in range(cols):
            if grid[i][j] == 1:
                count += 1
                # flood fill to clear this island
                stack = [(i, j)]
                while stack:
                    x, y = stack.pop()
                    if x < 0 or x >= rows:
                        continue
                    if y < 0 or y >= len(grid[x]):
                        continue
                    if grid[x][y] != 1:
                        continue
                    grid[x][y] = 0  # mark visited
                    for dx, dy in ((1,0),(-1,0),(0,1),(0,-1)):
                        stack.append((x+dx, y+dy))
    return count

